using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer.Tools;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Gets the current environment name")]
    public static string GetEnvironment() => "Production";

    [McpServerTool, Description("Echoes a message back to the caller")]
    public static string Echo(string message) => $"Echo: {message}";
}

using ModelContextProtocol.Server;

namespace McpHttpServer.Resources;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(
        Uri = "config://app/settings",
        Name = "App Settings",
        Description = "Returns the application configuration data")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            MaxConnections = 100,
            Features = new[] { "tools", "resources", "http-transport" }
        };
        return System.Text.Json.JsonSerializer.Serialize(config, new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }
}

